#!/usr/bin/env python3
import sys
import subprocess
import threading

last_moves = []

def main():
    p = subprocess.Popen(["/usr/local/bin/stockfish"], stdin=subprocess.PIPE, stdout=subprocess.PIPE, text=True)

    def read_stdout():
        for line in p.stdout:
            if line.startswith("bestmove"):
                if len(last_moves) == 2:
                    best = "g1e2"
                elif len(last_moves) == 4:
                    best = "g2g3"
                elif len(last_moves) == 6:
                    best = "a2a3"
                else:
                    best = "a2a3"
                print(f"bestmove {best}")
                sys.stdout.flush()
            else:
                print(line, end="")
                sys.stdout.flush()

    t = threading.Thread(target=read_stdout)
    t.daemon = True
    t.start()

    global last_moves
    for line in sys.stdin:
        if line.startswith("position"):
            if "moves " in line:
                last_moves = line.split("moves ")[1].split()
            else:
                last_moves = []
        p.stdin.write(line)
        p.stdin.flush()

if __name__ == "__main__":
    main()
EOF
